V C_PvpUITests::m_local_draft(const Args& A) {
    V L_app = A.get(0, SY("app"), nullptr, "local_draft");
    V L_stop_stage = (A.size() > 1 || A.has_kw(SY("stop_stage"))) ? A.get(1, SY("stop_stage"), nullptr) : V(V::none());
    V L_wanted = (A.size() > 2 || A.has_kw(SY("wanted"))) ? A.get(2, SY("wanted"), nullptr) : V(V::none());
    V L_before;
    V L_candidates;
    V L_decks;
    V L_key;
    V L_protected_;
    V L_side;
    V L_turn;
    V L_validator;
    L_wanted = py_or(L_wanted, [&]() -> V { return py_dict({}); });
    L_protected_ = py::set_it(py::sum_it(callm(L_wanted, SY("values"), Args{}), V::list({})));
    while (((py::m_get(pvz::getattr(L_app, SY("view")), SV("draft_stage")) != SV("complete")) && (py::m_get(pvz::getattr(L_app, SY("view")), SV("draft_stage")) != L_stop_stage))) {
        L_turn = callm(pvz::getattr(L_app, SY("room")), SY("_draft_action"), Args{});
        L_side = rd(pvz::getattr(L_app, SY("view")), SV("current_side"));
        L_before = pvz::getattr(pvz::getattr(L_app, SY("room")), SY("revision"));
        L_decks = py::stdlib_call(SV("copy.deepcopy"), Args{pvz::getattr(pvz::getattr(L_app, SY("room")), SY("decks"))});
        if (((rd(L_turn, SV("kind")) == SV("ban")) && (rd(L_turn, SV("category")) == SV("secret")))) {
            (void)(callm(L_app, SY("action"), Args{V::tuple({SV("skip_ban")})}));
        } else {
            L_validator = ((rd(L_turn, SV("kind")) == SV("ban")) ? V(pvz::getattr(pvz::getattr(L_app, SY("room")), SY("_ban_error"))) : V(pvz::getattr(pvz::getattr(L_app, SY("room")), SY("_pick_error"))));
            L_candidates = (((rd(L_turn, SV("kind")) == SV("pick")) ? V((py::m_get(L_wanted, L_side, V::list({})) + callm(pvz::getattr(L_app, SY("room")), SY("_default_deck"), Args{L_side}))) : V(V::list({}))) + py::list_it(pm_catalog::CARDS));
            L_key = py::next([&]() -> V { V out_ = V::list(); V L_k; { V it1_ = py::iter_list(L_candidates); for (size_t i1_ = 0; i1_ < it1_.len(); ++i1_) { L_k = it1_.idx(int64_t(i1_)); if (!((!((L_validator).call(Args{L_side, L_k})).truthy() && ((rd(L_turn, SV("kind")) != SV("ban")) || (!py::in(L_k, L_protected_) && !(py::m_get(rd(pm_catalog::CARDS, L_k), SV("producer"))).truthy()))))) continue; out_.append(L_k); }}return out_; }());
            (void)(callm(L_app, SY("action"), Args{V::tuple({SV("card"), L_key})}));
            (void)(m_assertEqual(Args{pvz::getattr(pvz::getattr(L_app, SY("room")), SY("revision")), L_before}));
            (void)(m_assertEqual(Args{pvz::getattr(pvz::getattr(L_app, SY("room")), SY("decks")), L_decks}));
            (void)(callm(L_app, SY("action"), Args{V::tuple({SV("advance")})}));
        }
        (void)(m_assertGreater(Args{pvz::getattr(pvz::getattr(L_app, SY("room")), SY("revision")), L_before}));
    }
    return V::none();
}

